// stays as they are.
func (q *Queries) UpsertInvitedMember(ctx context.Context, arg UpsertInvitedMemberParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertInvitedMember,
		arg.AdministrationID,
		arg.UserID,
		arg.UserType,
		arg.Permissions,
		arg.CreatedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

